import { useMemo, useState } from 'react';
import { Activity, AlertTriangle, ArrowDownRight, ArrowUpRight, BatteryCharging, Bell, BookOpen, Bus, Check, ChevronDown, ChevronLeft, ChevronRight, CloudRain, Command, Compass, Download, ExternalLink, Gauge, GitBranch, GraduationCap, LayoutDashboard, MapPin, Menu, Moon, MoreHorizontal, RadioTower, RefreshCw, Search, Settings, ShieldCheck, ShieldX, SlidersHorizontal, Sparkles, Sun, Thermometer, TrendingUp, Wifi, X, Zap } from 'lucide-react';
import { Area, AreaChart, Bar, BarChart, CartesianGrid, Cell, Line, LineChart, Pie, PieChart, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import { estimateRisk, validatePredictionInput } from './services/prediction';
import { makeDemoEvents, simulate, twinConfigs } from './services/simulation';
import type { PredictionInput, ScenarioResult, SensorEvent } from './types';

const navGroups = [
  { label: 'WORKSPACE', items: [
    { id: 'Overview', icon: LayoutDashboard }, { id: 'AI Predictions', icon: Sparkles }, { id: 'Weather Intelligence', icon: CloudRain }, { id: 'Energy & Sensors', icon: BatteryCharging }, { id: 'Transport Monitoring', icon: Bus }, { id: 'School Attendance', icon: GraduationCap },
  ]},
  { label: 'DIGITAL TWINS', items: [ { id: 'Scenario Simulator', icon: GitBranch }, { id: 'Twin Explorer', icon: Compass }, { id: 'Intervention Center', icon: SlidersHorizontal } ]},
  { label: 'GOVERNANCE', items: [ { id: 'Trust Center', icon: ShieldCheck }, { id: 'Data Sources', icon: RadioTower }, { id: 'Settings', icon: Settings } ]},
];
const trendData = [ { time: '01:00', risk: 18, rain: 3, temp: 27 }, { time: '03:00', risk: 22, rain: 6, temp: 27 }, { time: '05:00', risk: 28, rain: 11, temp: 26 }, { time: '07:00', risk: 48, rain: 29, temp: 27 }, { time: '09:00', risk: 61, rain: 52, temp: 29 }, { time: '11:00', risk: 54, rain: 34, temp: 31 }, { time: '13:00', risk: 43, rain: 20, temp: 33 } ];
const transportData = [ { route: 'R1', delay: 12 }, { route: 'R2', delay: 27 }, { route: 'R3', delay: 43 }, { route: 'R4', delay: 18 }, { route: 'R5', delay: 34 } ];
const energyData = [ { time: '06:00', usage: 52 }, { time: '07:00', usage: 68 }, { time: '08:00', usage: 78 }, { time: '09:00', usage: 72 }, { time: '10:00', usage: 84 }, { time: '11:00', usage: 76 }, { time: '12:00', usage: 89 } ];
const attendanceData = [ { day: 'Mon', rate: 94 }, { day: 'Tue', rate: 91 }, { day: 'Wed', rate: 88 }, { day: 'Thu', rate: 82 }, { day: 'Fri', rate: 86 }, { day: 'Sat', rate: 95 }, { day: 'Sun', rate: 97 } ];
const initialInput: PredictionInput = { rainfall: 84, temperature: 33, outageHours: 1.5, transportDelay: 28 };
const fmt = (n: number) => new Intl.NumberFormat('en-IN').format(n);

function App() {
  const [page, setPage] = useState('Overview');
  const [mobileNav, setMobileNav] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const [input, setInput] = useState<PredictionInput>(initialInput);
  const [prediction, setPrediction] = useState(() => estimateRisk(initialInput));
  const [errors, setErrors] = useState<string[]>([]);
  const [events, setEvents] = useState<SensorEvent[]>(makeDemoEvents());
  const [tampered, setTampered] = useState(false);
  const [toast, setToast] = useState('');
  const [refresh, setRefresh] = useState(0);
  const [scenario, setScenario] = useState('Heavy rainfall');
  const [customTwin, setCustomTwin] = useState(false);
  const [showAlerts, setShowAlerts] = useState(false);
  const [settings, setSettings] = useState({ demo: true, notifications: true, metric: 'LAI' });
  const currentScenarioInput = useMemo(() => scenario === 'Heatwave' ? { ...input, temperature: Math.max(input.temperature, 41), rainfall: Math.min(input.rainfall, 20) } : scenario === 'Power dip' ? { ...input, outageHours: Math.max(input.outageHours, 5), temperature: Math.max(input.temperature, 34) } : scenario === 'Heavy rainfall' ? { ...input, rainfall: Math.max(input.rainfall, 145), transportDelay: Math.max(input.transportDelay, 48) } : input, [scenario, input]);
  const base = useMemo(() => simulate(currentScenarioInput), [currentScenarioInput]);
  const interventions = useMemo(() => ['Baseline', 'Extra shuttle buses', 'Shift school hours', 'Off-peak pre-cooling'].map(n => simulate(currentScenarioInput, n)), [currentScenarioInput]);
  const lai = base.lai;

  const notify = (message: string) => { setToast(message); window.setTimeout(() => setToast(''), 2800); };
  const updateInput = (key: keyof PredictionInput, value: string) => setInput(prev => ({ ...prev, [key]: value === '' ? Number.NaN : Number(value) }));
  const runPrediction = () => { const found = validatePredictionInput(input); setErrors(found); if (found.length) { notify('Please correct the highlighted input values.'); return; } setPrediction(estimateRisk(input)); notify('Illustrative risk estimate recalculated.'); };
  const runScenario = () => { setPage('Scenario Simulator'); notify('Scenario simulated with deterministic demo rules.'); };
  const tamperEvent = () => {
    if (tampered) { setEvents(makeDemoEvents()); setTampered(false); notify('Demo events reset.'); return; }
    setEvents(prev => prev.map((e, i) => i === 2 ? { ...e, value: '12 min (modified)', status: 'Rejected', reason: 'Payload was modified after signing. Signature verification failed; this event was not applied to trusted simulation inputs.' } : e));
    setTampered(true); notify('Tamper attempt detected; trusted simulation unchanged.');
  };
  const exportReport = () => {
    const report = { product: 'PulseTwin', mode: 'Illustrative demo', generatedAt: new Date().toISOString(), scenario, input: currentScenarioInput, riskEstimate: prediction, baseline: base, interventions, events };
    const blob = new Blob([JSON.stringify(report, null, 2)], { type: 'application/json' }); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href = url; a.download = 'pulsetwin-demo-report.json'; a.click(); URL.revokeObjectURL(url); notify('Demo report exported.');
  };
  const choosePage = (id: string) => { setPage(id); setMobileNav(false); };

  return <div className="app-shell">
    <aside className={`sidebar ${collapsed ? 'sidebar-collapsed' : ''} ${mobileNav ? 'sidebar-mobile-open' : ''}`}>
      <div className="brand-row"><div className="brand-mark"><Activity size={21} strokeWidth={2.6}/></div>{!collapsed && <div className="brand-word">pulse<span>twin</span><small>EDUCATION CONTINUITY</small></div>}<button className="icon-btn sidebar-collapse" aria-label="Collapse sidebar" onClick={() => setCollapsed(v => !v)}><ChevronLeft size={17}/></button></div>
      <div className="workspace-switch"><div className="workspace-avatar">RC</div>{!collapsed && <><div className="workspace-copy"><strong>Regional Command</strong><span>Demo workspace</span></div><ChevronDown size={15}/></>}</div>
      <nav className="main-nav">{navGroups.map(group => <div className="nav-group" key={group.label}><div className="nav-label">{!collapsed ? group.label : '···'}</div>{group.items.map(item => { const Icon = item.icon; return <button key={item.id} title={collapsed ? item.id : undefined} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => choosePage(item.id)}><Icon size={18}/>{!collapsed && <span>{item.id}</span>}{!collapsed && item.id === 'Trust Center' && <span className="nav-count">3</span>}</button>; })}</div>)}</nav>
      {!collapsed && <div className="sidebar-bottom"><div className="sidebar-weather"><div className="weather-icon"><CloudRain size={20}/></div><div><span>MONSOON WATCH</span><strong>84 mm <small>· simulated</small></strong><p>Regional rainfall scenario</p></div></div><div className="sidebar-profile"><div className="profile-avatar">AD</div><div><strong>Admin Demo</strong><span>Planning analyst</span></div><MoreHorizontal size={18}/></div></div>}
    </aside>
    {mobileNav && <button className="mobile-scrim" aria-label="Close navigation" onClick={() => setMobileNav(false)} />}
    <main className="main-area">
      <header className="topbar"><div className="topbar-left"><button className="icon-btn mobile-menu" aria-label="Open navigation" onClick={() => setMobileNav(true)}><Menu size={20}/></button><div className="breadcrumb">PulseTwin <ChevronRight size={14}/><strong>{page}</strong></div></div><div className="topbar-actions"><div className="demo-pill"><span className="live-dot"/> DEMO MODE</div><div className="header-divider"/><button className="icon-btn" aria-label="Refresh demo data" onClick={() => { setRefresh(v => v + 1); notify('Demo state refreshed; no live feed was requested.'); }}><RefreshCw size={17}/></button><button className="icon-btn notification-button" aria-label="Open notifications" onClick={() => setShowAlerts(v => !v)}><Bell size={18}/><i/></button><div className="topbar-avatar">AD</div></div></header>
      {showAlerts && <div className="notification-popover"><div className="popover-head"><strong>Notifications</strong><button className="icon-btn" onClick={() => setShowAlerts(false)} aria-label="Close notifications"><X size={15}/></button></div><p><AlertTriangle size={15}/> High rainfall scenario active</p><p><ShieldX size={15}/> One demo event rejected</p><p><Zap size={15}/> Campus grid status intermittent</p></div>}
      <div className="page-content" key={page}>
        <div className="page-heading"><div><div className="eyebrow">REGIONAL EDUCATION RESILIENCE <span>•</span> {new Date().toLocaleDateString('en-IN', { day: '2-digit', month: 'short', year: 'numeric' })}</div><h1>{page === 'Overview' ? 'Good morning, planner' : page}</h1><p>{pageDescription(page)}</p></div><div className="heading-actions"><button className="btn btn-quiet" onClick={exportReport}><Download size={16}/> Export report</button><button className="btn btn-primary" onClick={runScenario}><Sparkles size={16}/> Run scenario</button></div></div>
        {page === 'Overview' && <OverviewPage lai={lai} prediction={prediction} base={base} events={events} refresh={refresh} setPage={choosePage} runScenario={runScenario}/>}
        {page === 'AI Predictions' && <PredictionsPage input={input} updateInput={updateInput} runPrediction={runPrediction} prediction={prediction} errors={errors} setInput={setInput} setPage={choosePage}/>}
        {page === 'Weather Intelligence' && <WeatherPage scenario={scenario} setScenario={setScenario} input={currentScenarioInput}/>}
        {page === 'Energy & Sensors' && <EnergyPage events={events} setPage={choosePage}/>}
        {page === 'Transport Monitoring' && <TransportPage base={base} scenario={scenario}/>}
        {page === 'School Attendance' && <AttendancePage lai={lai} base={base}/>}
        {page === 'Scenario Simulator' && <ScenarioPage scenario={scenario} setScenario={setScenario} interventions={interventions} input={currentScenarioInput} setInput={setInput} setPage={choosePage}/>}
        {page === 'Twin Explorer' && <TwinPage customTwin={customTwin} setCustomTwin={setCustomTwin}/>}
        {page === 'Intervention Center' && <InterventionPage interventions={interventions} base={base} setPage={choosePage}/>}
        {page === 'Trust Center' && <TrustPage events={events} tampered={tampered} tamperEvent={tamperEvent} refresh={refresh}/>}
        {page === 'Data Sources' && <DataSourcesPage events={events} setPage={choosePage}/>}
        {page === 'Settings' && <SettingsPage settings={settings} setSettings={setSettings}/>}
        <footer className="page-footer"><span><span className="footer-dot"/> All metrics are illustrative · Not an official weather warning</span><span>PulseTwin prototype <b>v1.0.0</b> <span className="footer-sep">/</span> {refresh > 0 ? `Refreshed ${refresh}×` : 'Deterministic demo data'}</span></footer>
      </div>
    </main>
    {toast && <div className="toast"><Check size={17}/>{toast}</div>}
  </div>;
}

function pageDescription(page: string) {
  const descriptions: Record<string, string> = {
    'Overview': 'Understand how weather, mobility and campus operations combine to protect learning access.',
    'AI Predictions': 'Explore a transparent, rule-based estimate of potential education disruption.',
    'Weather Intelligence': 'Monitor scenario-based weather signals and the modeled downstream cascade.',
    'Energy & Sensors': 'Review campus power availability, energy demand and sensor data quality.',
    'Transport Monitoring': 'Track modeled route delays and the effect on on-time campus access.',
    'School Attendance': 'Connect access and classroom functionality to an aggregated Learning Access Index.',
    'Scenario Simulator': 'Run reproducible disruption scenarios through connected town and campus twins.',
    'Twin Explorer': 'Explore how the town twin connects to campus operations and learning access.',
    'Intervention Center': 'Compare re-simulated actions against one consistent baseline.',
    'Trust Center': 'Inspect event validation, rejection reasons and the demo audit trail.',
    'Data Sources': 'Understand source freshness, validation, trust and adapter readiness.',
    'Settings': 'Configure this browser demo and its presentation preferences.',
  };
  return descriptions[page] ?? 'Education continuity intelligence for resilient learning communities.';
}

function SectionTitle({ title, subtitle, action }: { title: string; subtitle?: string; action?: React.ReactNode }) { return <div className="section-title"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action}</div>; }
function MetricCard({ title, value, unit, change, tone = 'blue', icon, foot }: { title: string; value: string; unit?: string; change?: string; tone?: string; icon: React.ReactNode; foot?: string }) { return <div className="metric-card"><div className="metric-top"><span>{title}</span><div className={`metric-icon ${tone}`}>{icon}</div></div><div className="metric-value">{value}<small>{unit}</small></div><div className="metric-bottom">{change && <span className={`change ${change.startsWith('-') ? 'positive' : 'negative'}`}>{change.startsWith('-') ? <ArrowDownRight size={13}/> : <ArrowUpRight size={13}/>} {change}</span>}<span>{foot}</span></div></div>; }
function ChartCard({ title, subtitle, children, action }: { title: string; subtitle?: string; children: React.ReactNode; action?: React.ReactNode }) { return <section className="panel chart-panel"><div className="panel-header"><div><h2>{title}</h2>{subtitle && <p>{subtitle}</p>}</div>{action ?? <button className="icon-btn tiny" aria-label={`More options for ${title}`}><MoreHorizontal size={18}/></button>}</div>{children}</section>; }

function OverviewPage({ lai, prediction, base, events, refresh, setPage, runScenario }: { lai: number; prediction: ReturnType<typeof estimateRisk>; base: ScenarioResult; events: SensorEvent[]; refresh: number; setPage: (s: string) => void; runScenario: () => void }) {
  return <>
    <div className="metric-grid"><MetricCard title="Learning Access Index" value={String(lai)} unit="/100" change="-4.2%" tone="violet" icon={<BookOpen size={18}/>} foot="vs. normal-day baseline"/><MetricCard title="Disruption risk" value={String(prediction.score)} unit="/100" change="+8.6%" tone="coral" icon={<Activity size={18}/>} foot={`${prediction.category} · rule-based estimate`}/><MetricCard title="Weather scenario" value="High" tone="cyan" icon={<CloudRain size={18}/>} foot="84 mm rainfall · simulated"/><MetricCard title="Campus energy" value="72" unit="% available" change="+2.1%" tone="green" icon={<Zap size={18}/>} foot="Illustrative grid status"/></div>
    <div className="dashboard-grid dashboard-main-grid"><ChartCard title="Disruption risk trend" subtitle="Modeled risk score over the last 12 hours" action={<span className="chart-legend"><i className="legend-blue"/> Risk score <ChevronDown size={13}/></span>}><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData} margin={{ top: 12, right: 6, bottom: 0, left: -20 }}><defs><linearGradient id="riskFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#5d6af5" stopOpacity={0.24}/><stop offset="95%" stopColor="#5d6af5" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 11 }}/><YAxis domain={[0,100]} axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 11 }}/><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e8ebf2', fontSize: 12 }}/><Area type="monotone" dataKey="risk" stroke="#6571f5" strokeWidth={2.5} fill="url(#riskFill)" activeDot={{ r: 5, strokeWidth: 0 }}/></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span><i className="status-dot medium"/> Current scenario risk: <b>{prediction.score}/100</b></span><span>All values simulated</span></div></ChartCard>
      <section className="panel twin-panel"><div className="panel-header"><div><h2>Connected twin status</h2><p>Weather → town → campus → learning access</p></div><button className="text-action" onClick={() => setPage('Twin Explorer')}>Explore twins <ChevronRight size={14}/></button></div><div className="twin-visual"><div className="twin-orbit orbit-one"/><div className="twin-orbit orbit-two"/><div className="twin-node town-node"><CloudRain size={19}/><strong>Town</strong><span>Weather + roads</span><em>Elevated</em></div><div className="twin-connector"><span/><span/><span/></div><div className="twin-node campus-node"><GraduationCap size={19}/><strong>Campus</strong><span>Power + classrooms</span><em>Monitoring</em></div><div className="map-grid-lines"/></div><div className="twin-legend"><span><i className="status-dot high"/> Disruption propagates</span><span><i className="status-dot good"/> Trusted inputs only</span></div><button className="outline-full" onClick={() => setPage('Scenario Simulator')}><GitBranch size={15}/> Open scenario simulator</button></section></div>
    <div className="dashboard-grid dashboard-lower-grid"><ChartCard title="Rainfall & temperature" subtitle="Illustrative weather history"><div className="chart-wrap short"><ResponsiveContainer width="100%" height="100%"><LineChart data={trendData} margin={{ top: 8, right: 6, bottom: 0, left: -20 }}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 10 }}/><YAxis yAxisId="rain" axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 10 }}/><YAxis yAxisId="temp" orientation="right" axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 10 }}/><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e8ebf2', fontSize: 12 }}/><Line yAxisId="rain" type="monotone" dataKey="rain" name="Rainfall (mm)" stroke="#4c9cf5" strokeWidth={2.2} dot={false}/><Line yAxisId="temp" type="monotone" dataKey="temp" name="Temperature (°C)" stroke="#f0a24c" strokeWidth={2.2} dot={false}/></LineChart></ResponsiveContainer></div><div className="mini-legend"><span><i className="legend-blue"/> Rainfall (mm)</span><span><i className="legend-orange"/> Temperature (°C)</span></div></ChartCard>
      <ChartCard title="Campus energy demand" subtitle="Hourly modeled consumption · kW"><div className="chart-wrap short"><ResponsiveContainer width="100%" height="100%"><AreaChart data={energyData} margin={{ top: 8, right: 6, bottom: 0, left: -20 }}><defs><linearGradient id="energyFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#25b6a5" stopOpacity={0.22}/><stop offset="95%" stopColor="#25b6a5" stopOpacity={0.01}/></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="time" axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 10 }}/><YAxis axisLine={false} tickLine={false} tick={{ fill: '#8790a4', fontSize: 10 }}/><Tooltip contentStyle={{ borderRadius: 12, border: '1px solid #e8ebf2', fontSize: 12 }}/><Area type="monotone" dataKey="usage" name="Power (kW)" stroke="#27b6a5" strokeWidth={2.2} fill="url(#energyFill)"/></AreaChart></ResponsiveContainer></div><div className="chart-foot"><span><i className="status-dot good"/> Grid available <b>72%</b></span><span>Illustrative only</span></div></ChartCard>
      <section className="panel alerts-panel"><div className="panel-header"><div><h2>Recent alerts</h2><p>Signals requiring planner attention</p></div><button className="text-action" onClick={() => setPage('Data Sources')}>View all <ChevronRight size={14}/></button></div><div className="alert-list"><AlertRow tone="orange" icon={<CloudRain size={16}/>} title="Heavy rainfall scenario" description="North corridor · 84 mm / 3h" time="07:42" tag="HIGH"/><AlertRow tone="red" icon={<Zap size={16}/>} title="Grid intermittency" description="Campus block B · simulated" time="07:40" tag="MEDIUM"/><AlertRow tone="purple" icon={<ShieldX size={16}/>} title="Sensor payload rejected" description="Road sensor R4 · signature mismatch" time="07:39" tag="REJECTED"/></div></section></div>
    <div className="bottom-callout"><div className="callout-icon"><Sparkles size={20}/></div><div><strong>What if the weather gets worse?</strong><p>Compare practical actions against the same simulated baseline before making a plan.</p></div><button className="btn btn-primary" onClick={runScenario}>Open scenario lab <ChevronRight size={16}/></button></div>
  </>;
}
function AlertRow({ tone, icon, title, description, time, tag }: { tone: string; icon: React.ReactNode; title: string; description: string; time: string; tag: string }) { return <div className="alert-row"><div className={`alert-icon ${tone}`}>{icon}</div><div className="alert-copy"><strong>{title}</strong><span>{description}</span></div><div className="alert-meta"><span>{time}</span><b className={tone}>{tag}</b></div></div>; }

function PredictionsPage({ input, updateInput, runPrediction, prediction, errors, setInput, setPage }: { input: PredictionInput; updateInput: (key: keyof PredictionInput, value: string) => void; runPrediction: () => void; prediction: ReturnType<typeof estimateRisk>; errors: string[]; setInput: React.Dispatch<React.SetStateAction<PredictionInput>>; setPage: (s: string) => void }) {
  const fields: { key: keyof PredictionInput; label: string; unit: string; min: number; max: number; step: number; hint: string }[] = [ { key: 'rainfall', label: 'Rainfall', unit: 'mm', min: 0, max: 500, step: 1, hint: 'Accumulated rainfall estimate' }, { key: 'temperature', label: 'Temperature', unit: '°C', min: -10, max: 55, step: 0.5, hint: 'Ambient outdoor temperature' }, { key: 'outageHours', label: 'Power outage duration', unit: 'hours', min: 0, max: 72, step: 0.5, hint: 'Total modeled outage duration' }, { key: 'transportDelay', label: 'Transport delay', unit: 'minutes', min: 0, max: 240, step: 1, hint: 'Average route delay estimate' } ];
  return <div className="content-stack"><div className="info-banner"><Sparkles size={18}/><div><strong>Explainable prototype, not a trained AI model</strong><p>This deterministic weighted rule model shows how each input contributes. Scores are illustrative and are not calibrated probabilities or safety thresholds.</p></div></div><div className="two-col-layout"><section className="panel form-panel"><SectionTitle title="Disruption inputs" subtitle="Edit values to run a new estimate"/><div className="form-grid">{fields.map(f => <label className="field" key={f.key}><span>{f.label} <small>({f.unit})</small></span><div className="input-unit"><input type="number" min={f.min} max={f.max} step={f.step} value={Number.isFinite(input[f.key]) ? input[f.key] : ''} onChange={e => updateInput(f.key, e.target.value)} aria-label={f.label}/><span>{f.unit}</span></div><small className="field-hint">{f.hint} · {f.min}–{f.max}</small></label>)}</div>{errors.length > 0 && <div className="validation-box"><AlertTriangle size={16}/><div>{errors.map(e => <p key={e}>{e}</p>)}</div></div>}<div className="form-footer"><button className="btn btn-quiet" onClick={() => { setInput({ rainfall: 0, temperature: 28, outageHours: 0, transportDelay: 0 }); }}>Reset values</button><button className="btn btn-primary" onClick={runPrediction}><Sparkles size={16}/> Calculate estimate</button></div><div className="assumption-note"><strong>Model assumptions</strong><p>Weights: rainfall 32%, heat 18%, power 28%, transport 22%. Severity is normalized against configurable thresholds. Categories are Low (0–29), Medium (30–59), High (60–79), Critical (80–100).</p></div></section><section className="panel prediction-result"><div className="panel-header"><div><h2>Estimate result</h2><p>Latest rule-model output</p></div><span className="demo-tag">SIMULATED</span></div><div className="risk-score-display"><div className="score-ring" style={{ background: `conic-gradient(#6673f4 ${prediction.score * 3.6}deg, #edf0fc 0)` }}><div><strong>{prediction.score}</strong><span>of 100</span></div></div><div className="score-description"><span className={`severity-label ${prediction.category.toLowerCase()}`}>{prediction.category} risk</span><h3>Education disruption risk</h3><p>{prediction.explanation}</p></div></div><div className="factor-list"><h3>Factor breakdown</h3>{prediction.factors.map(f => <div className="factor-row" key={f.label}><div className="factor-label"><span>{f.label}</span><b>{f.contribution} pts</b></div><div className="factor-track"><span style={{width: `${f.severity}%`}}/></div><div className="factor-foot"><span>Severity {f.severity}%</span><span>Weight {Math.round(f.weight * 100)}%</span></div></div>)}</div><div className="result-actions"><button className="btn btn-primary" onClick={() => setPage('Scenario Simulator')}>Simulate this scenario <ChevronRight size={15}/></button></div><p className="timestamp-note">Calculated {new Date(prediction.createdAt).toLocaleString()}</p></section></div></div>;
}

function WeatherPage({ scenario, setScenario, input }: { scenario: string; setScenario: (s: string) => void; input: PredictionInput }) {
  return <div className="content-stack"><div className="weather-hero"><div className="weather-hero-content"><span className="hero-kicker"><CloudRain size={15}/> WEATHER INTELLIGENCE · DEMO</span><h2>Monsoon conditions can cascade into lost learning access.</h2><p>Explore illustrative weather conditions and see how they may affect transport and campus functionality in the connected twin.</p><div className="hero-stats"><div><strong>{input.rainfall}<small> mm</small></strong><span>Scenario rainfall</span></div><div><strong>{input.temperature}<small> °C</small></strong><span>Temperature</span></div><div><strong>{Math.round(Math.min(100, input.rainfall / 1.8))}<small>%</small></strong><span>Rainfall intensity index</span></div></div></div><div className="weather-art"><div className="sun-disc"/><div className="cloud-shape"><span/><span/><i/></div><div className="rain-streaks"><i/><i/><i/><i/><i/><i/><i/></div><div className="art-horizon"/></div></div><div className="metric-grid three-metrics"><MetricCard title="Rainfall accumulation" value={String(input.rainfall)} unit="mm" tone="cyan" icon={<CloudRain size={18}/>} foot="Scenario input"/><MetricCard title="Temperature" value={String(input.temperature)} unit="°C" tone="orange" icon={<Thermometer size={18}/>} foot="Scenario input"/><MetricCard title="Transport impact" value={`${Math.round(input.transportDelay + Math.min(1, input.rainfall / 180) * 22)} min`} tone="violet" icon={<Bus size={18}/>} foot="Modeled route delay"/></div><div className="two-col-layout"><ChartCard title="Rainfall trend" subtitle="Illustrative hourly history"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={trendData} margin={{ top: 10, right: 10, bottom: 0, left: -18 }}><defs><linearGradient id="rainFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#419af4" stopOpacity={0.24}/><stop offset="95%" stopColor="#419af4" stopOpacity={0.02}/></linearGradient></defs><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="time" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area dataKey="rain" name="Rainfall (mm)" stroke="#419af4" fill="url(#rainFill)" strokeWidth={2.4}/></AreaChart></ResponsiveContainer></div></ChartCard><section className="panel form-panel"><SectionTitle title="Choose a weather scenario" subtitle="These are synthetic scenarios, not forecasts"/><div className="scenario-choice-list">{[{id:'Heavy rainfall',desc:'Intense rainfall with route slowdowns',icon:<CloudRain size={18}/>,tone:'cyan'},{id:'Heatwave',desc:'High heat with increased cooling demand',icon:<Sun size={18}/>,tone:'orange'},{id:'Power dip',desc:'Grid intermittency during a disruption',icon:<Zap size={18}/>,tone:'violet'}].map(s => <button key={s.id} className={`scenario-choice ${scenario === s.id ? 'selected' : ''}`} onClick={() => setScenario(s.id)}><div className={`choice-icon ${s.tone}`}>{s.icon}</div><div><strong>{s.id}</strong><span>{s.desc}</span></div>{scenario === s.id && <Check size={17}/>}</button>)}</div><div className="cascade-note"><GitBranch size={17}/><p><strong>Downstream chain</strong><br/>Weather input → road accessibility → campus arrival → classroom functionality → LAI</p></div></section></div></div>;
}

function EnergyPage({ events, setPage }: { events: SensorEvent[]; setPage: (s: string) => void }) {
  const accepted = events.filter(e => e.status === 'Accepted').length; const rejected = events.length - accepted;
  return <div className="content-stack"><div className="metric-grid three-metrics"><MetricCard title="Grid availability" value="72%" tone="green" icon={<Zap size={18}/>} foot="Illustrative campus status"/><MetricCard title="Peak demand" value="89" unit="kW" tone="cyan" icon={<BatteryCharging size={18}/>} foot="Modeled at 12:00"/><MetricCard title="Sensor events" value={String(events.length)} tone="violet" icon={<RadioTower size={18}/>} foot={`${accepted} accepted · ${rejected} rejected`}/></div><div className="two-col-layout"><ChartCard title="Power demand profile" subtitle="Modeled hourly campus load"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><AreaChart data={energyData}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="time" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Area dataKey="usage" name="Demand (kW)" stroke="#23b6a4" fill="#23b6a41c" strokeWidth={2.4}/></AreaChart></ResponsiveContainer></div></ChartCard><section className="panel"><SectionTitle title="Sensor health" subtitle="Demo event validation summary"/><div className="health-score"><div className="health-circle"><strong>{Math.round(accepted / events.length * 100)}%</strong><span>accepted</span></div><div className="health-details"><div><i className="status-dot good"/> Accepted events <b>{accepted}</b></div><div><i className="status-dot high"/> Rejected events <b>{rejected}</b></div><div><i className="status-dot medium"/> Stale / missing <b>0</b></div></div></div><button className="outline-full" onClick={() => setPage('Trust Center')}><ShieldCheck size={15}/> Inspect verification log</button></section></div><section className="panel"><SectionTitle title="Recent energy & sensor events" subtitle="Synthetic sample events" action={<button className="text-action" onClick={() => setPage('Data Sources')}>Data source details <ChevronRight size={14}/></button>}/><EventTable events={events.slice(0, 4)}/></section></div>;
}

function TransportPage({ base, scenario }: { base: ScenarioResult; scenario: string }) {
  return <div className="content-stack"><div className="metric-grid three-metrics"><MetricCard title="Average route delay" value={`${base.transportDelay}`} unit="min" change="+12%" tone="coral" icon={<Bus size={18}/>} foot={`Under ${scenario.toLowerCase()} scenario`}/><MetricCard title="On-time access" value={`${base.onTime}%`} tone="green" icon={<ClockIcon/>} foot="Modeled arrival availability"/><MetricCard title="Routes monitored" value="5" tone="blue" icon={<MapPin size={18}/>} foot="Illustrative route set"/></div><div className="two-col-layout"><ChartCard title="Delay by route" subtitle="Estimated delay in minutes"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={transportData} barSize={28}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="route" axisLine={false} tickLine={false}/><YAxis axisLine={false} tickLine={false}/><Tooltip/><Bar dataKey="delay" name="Delay (min)" radius={[6,6,0,0]}>{transportData.map((entry, i) => <Cell key={entry.route} fill={i === 2 ? '#f19a67' : '#6874f5'}/>)}</Bar></BarChart></ResponsiveContainer></div></ChartCard><section className="panel"><SectionTitle title="Route status" subtitle="Town twin · illustrative only"/><div className="route-list">{transportData.map((r, i) => <div className="route-row" key={r.route}><div className={`route-badge ${i === 2 ? 'warning' : ''}`}>{r.route}</div><div className="route-copy"><strong>{['North corridor','River bridge','Market road','East connector','Coastal link'][i]}</strong><span>{i === 2 ? 'Waterlogging exposure modeled' : 'Route status estimated'}</span></div><div className="route-delay"><strong>{Math.round(r.delay + (base.transportDelay - 28) * 0.3)} min</strong><span>{i === 2 ? 'Elevated' : 'Moderate'}</span></div></div>)}</div></section></div><div className="info-banner compact"><MapPin size={18}/><div><strong>Regional schematic only</strong><p>No live map, GPS tracking or actual road conditions are connected in this demo.</p></div></div></div>;
}
function ClockIcon() { return <Activity size={18}/>; }

function AttendancePage({ lai, base }: { lai: number; base: ScenarioResult }) {
  const data = attendanceData.map((d, i) => ({ ...d, rate: Math.max(0, d.rate - (100 - base.lai) * (i > 2 ? 0.12 : 0.05)) }));
  return <div className="content-stack"><div className="metric-grid three-metrics"><MetricCard title="Learning Access Index" value={String(lai)} unit="/100" tone="violet" icon={<BookOpen size={18}/>} foot="Aggregated cohort estimate"/><MetricCard title="Modeled on-time access" value={`${base.onTime}%`} tone="green" icon={<GraduationCap size={18}/>} foot="Not observed attendance"/><MetricCard title="Classroom functionality" value={`${base.classroomFunction}%`} tone="cyan" icon={<Activity size={18}/>} foot="Energy + heat model"/></div><div className="two-col-layout"><ChartCard title="Attendance access trend" subtitle="Illustrative weekly pattern · percent"><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><LineChart data={data}><CartesianGrid strokeDasharray="3 4" vertical={false} stroke="#edf0f5"/><XAxis dataKey="day" axisLine={false} tickLine={false}/><YAxis domain={[60,100]} axisLine={false} tickLine={false}/><Tooltip/><Line dataKey="rate" name="Access estimate (%)" stroke="#6974f6" strokeWidth={2.5} dot={{ r: 3, fill: '#6974f6' }}/></LineChart></ResponsiveContainer></div></ChartCard><section className="panel lai-panel"><div className="panel-header"><div><h2>Learning Access Index</h2><p>Transparent composite indicator</p></div><span className="demo-tag">ILLUSTRATIVE</span></div><div className="lai-big"><strong>{lai}</strong><span>/ 100</span></div><div className="lai-formula"><div><span>On-time access</span><b>62%</b><div className="factor-track"><span style={{width: `${base.onTime}%`}}/></div></div><div><span>Classroom functionality</span><b>38%</b><div className="factor-track teal"><span style={{width: `${base.classroomFunction}%`}}/></div></div></div><div className="formula-note"><code>LAI = 0.62 × access + 0.38 × functionality</code><p>Scores estimate continuity conditions for aggregated cohorts. They are not measured student attendance or individual outcomes.</p></div></section></div></div>;
}

function ScenarioPage({ scenario, setScenario, interventions, input, setInput, setPage }: { scenario: string; setScenario: (s: string) => void; interventions: ScenarioResult[]; input: PredictionInput; setInput: React.Dispatch<React.SetStateAction<PredictionInput>>; setPage: (s: string) => void }) {
  const [rainfall, setRainfall] = useState(input.rainfall);
  const [temperature, setTemperature] = useState(input.temperature);
  const [outage, setOutage] = useState(input.outageHours);
  const [delay, setDelay] = useState(input.transportDelay);
  const [ran, setRan] = useState(false);
  const run = () => { setInput({ rainfall, temperature, outageHours: outage, transportDelay: delay }); setRan(true); };
  return <div className="content-stack"><div className="info-banner"><GitBranch size={18}/><div><strong>Connected twin simulation</strong><p>Weather affects roads and transit; transport affects arrival access; heat and power affect classroom functionality. All calculations are deterministic demo rules.</p></div></div><div className="scenario-layout"><section className="panel scenario-controls"><SectionTitle title="Scenario controls" subtitle="Adjust the disruption profile"/><label className="field"><span>Scenario preset</span><select value={scenario} onChange={e => setScenario(e.target.value)}><option>Heavy rainfall</option><option>Heatwave</option><option>Power dip</option><option>Custom</option></select></label>{[{label:'Rainfall',unit:'mm',value:rainfall,set:setRainfall,min:0,max:250},{label:'Temperature',unit:'°C',value:temperature,set:setTemperature,min:15,max:50},{label:'Power outage',unit:'hours',value:outage,set:setOutage,min:0,max:12},{label:'Transport delay',unit:'min',value:delay,set:setDelay,min:0,max:180}].map(f => <div className="range-field" key={f.label}><div><label>{f.label}</label><b>{f.value} <small>{f.unit}</small></b></div><input type="range" min={f.min} max={f.max} value={f.value} onChange={e => f.set(Number(e.target.value) as never)}/><div className="range-limits"><span>{f.min}</span><span>{f.max} {f.unit}</span></div></div>)}<button className="btn btn-primary full-btn" onClick={run}><Sparkles size={16}/> Re-run simulation</button>{ran && <p className="success-inline"><Check size={14}/> Simulation inputs updated across the workspace.</p>}</section><div className="scenario-results"><div className="cascade-flow"><div className="cascade-node"><CloudRain size={19}/><strong>Weather</strong><span>{rainfall} mm · {temperature}°C</span></div><div className="cascade-arrow"><ChevronRight size={18}/></div><div className="cascade-node"><Bus size={19}/><strong>Town access</strong><span>{delay} min + rain impact</span></div><div className="cascade-arrow"><ChevronRight size={18}/></div><div className="cascade-node"><GraduationCap size={19}/><strong>Campus</strong><span>{outage}h outage exposure</span></div></div><section className="panel"><SectionTitle title="Intervention comparison" subtitle="Every action is re-simulated against the same baseline" action={<button className="text-action" onClick={() => setPage('Intervention Center')}>Optimize actions <ChevronRight size={14}/></button>}/><div className="comparison-table-wrap"><table className="comparison-table"><thead><tr><th>Intervention</th><th>LAI</th><th>On-time</th><th>Delay</th><th>Est. cost</th></tr></thead><tbody>{interventions.map((r, i) => <tr key={r.name} className={i === 0 ? 'baseline-row' : ''}><td><span className={`intervention-dot i${i}`}/><strong>{r.name}</strong>{i === 0 && <small>BASELINE</small>}</td><td><b>{r.lai}</b><span className={`delta ${r.lai >= interventions[0].lai ? 'up' : 'down'}`}>{i === 0 ? '—' : `${r.lai - interventions[0].lai > 0 ? '+' : ''}${r.lai - interventions[0].lai}`}</span></td><td>{r.onTime}%</td><td>{r.transportDelay} min</td><td>{r.cost === 0 ? '—' : `₹${r.cost}`}</td></tr>)}</tbody></table></div><p className="table-note">Costs and emissions are illustrative planning assumptions, not quotes. Best results depend on local constraints not modeled here.</p></section></div></div></div>;
}

function TwinPage({ customTwin, setCustomTwin }: { customTwin: boolean; setCustomTwin: (v: boolean) => void }) {
  return <div className="content-stack"><div className="twin-explorer-banner"><div><span className="hero-kicker"><Compass size={15}/> DIGITAL TWIN NETWORK</span><h2>One disruption. Connected consequences.</h2><p>PulseTwin links town conditions to campus operations and a shared learning-access outcome.</p></div><div className="network-illustration"><div className="network-circle nc1"><CloudRain size={22}/></div><div className="network-circle nc2"><Bus size={22}/></div><div className="network-circle nc3"><GraduationCap size={22}/></div><span className="network-line nl1"/><span className="network-line nl2"/></div></div><div className="twin-card-grid">{twinConfigs.map((t, i) => <div className="panel twin-detail-card" key={t.id}><div className={`twin-card-icon ${i ? 'campus' : 'town'}`}>{i ? <GraduationCap size={22}/> : <MapPin size={22}/>}</div><div className="twin-card-top"><span className="demo-tag">CONFIG-REGISTERED</span><span className="status-text"><i className="status-dot good"/> Active</span></div><h3>{t.name}</h3><p>{i ? 'Models energy, classroom functionality and aggregated learning access.' : 'Models rainfall exposure, road accessibility and transport delays.'}</p><div className="twin-detail-stats"><div><span>Twin type</span><strong>{t.type}</strong></div><div><span>{i ? 'Expected students' : 'Linked modules'}</span><strong>{i ? fmt(t.expected_students) : t.enabled_modules.length}</strong></div></div><div className="module-tags">{t.enabled_modules.map(m => <span key={m}>{m.replace('_',' ')}</span>)}</div></div>)}{customTwin && <div className="panel twin-detail-card new-twin-card"><div className="twin-card-icon new"><Sparkles size={22}/></div><div className="twin-card-top"><span className="demo-tag">LOCAL CONFIG</span><span className="status-text"><i className="status-dot good"/> Registered</span></div><h3>Community Learning Hub</h3><p>Example third twin registered from a demo configuration to show extensibility.</p><div className="twin-detail-stats"><div><span>Twin type</span><strong>campus</strong></div><div><span>Expected students</span><strong>350</strong></div></div><div className="module-tags"><span>energy</span><span>classrooms</span><span>learning access</span></div></div>}</div><div className="bottom-callout"><div className="callout-icon"><Command size={20}/></div><div><strong>Configuration-based expansion</strong><p>Register an additional twin using JSON settings without duplicating the simulation engine.</p></div><button className="btn btn-primary" onClick={() => setCustomTwin(!customTwin)}>{customTwin ? 'Remove demo twin' : 'Register demo twin'} <ChevronRight size={16}/></button></div><section className="panel code-panel"><SectionTitle title="Twin configuration example" subtitle="configs/twins/community-hub.json"/><pre>{JSON.stringify({ id: 'community-hub', name: 'Community Learning Hub', type: 'campus', expected_students: 350, linked_twins: ['town'], enabled_modules: ['energy', 'classrooms', 'learning_access'] }, null, 2)}</pre></section></div>;
}

function InterventionPage({ interventions, base, setPage }: { interventions: ScenarioResult[]; base: ScenarioResult; setPage: (s: string) => void }) {
  const best = [...interventions.slice(1)].sort((a,b) => b.lai - a.lai)[0];
  return <div className="content-stack"><div className="info-banner"><SlidersHorizontal size={18}/><div><strong>Decision support, not an automatic decision</strong><p>Interventions are compared using the same baseline. Cost and CO₂e estimates are illustrative; staffing, access equity, safety and feasibility require local review.</p></div></div><div className="intervention-hero"><div><span className="hero-kicker"><Sparkles size={15}/> MODELED RECOMMENDATION</span><h2>{best?.name ?? 'Compare interventions'}</h2><p>Among the currently modeled actions, this option has the highest Learning Access Index under the selected scenario.</p><div className="recommended-metrics"><div><strong>{best?.lai ?? base.lai}</strong><span>LAI score</span></div><div><strong>+{(best?.lai ?? base.lai) - base.lai}</strong><span>vs. baseline</span></div><div><strong>₹{best?.cost ?? 0}</strong><span>Illustrative cost</span></div></div></div><div className="recommendation-badge"><ShieldCheck size={25}/><span>SIMULATION-BASED</span></div></div><section className="panel"><SectionTitle title="Action comparison" subtitle="Impact, costs and assumptions"/><div className="intervention-cards">{interventions.slice(1).map((r, i) => <div className="intervention-card" key={r.name}><div className={`intervention-card-icon ic${i}`}>{i === 0 ? <Bus size={20}/> : i === 1 ? <ClockIcon/> : <Zap size={20}/>}</div><div className="intervention-card-head"><h3>{r.name}</h3>{r.name === best?.name && <span className="best-tag">Highest LAI</span>}</div><div className="intervention-lai"><strong>{r.lai}</strong><span>LAI</span><em className={r.lai >= base.lai ? 'up' : 'down'}>{r.lai - base.lai > 0 ? '+' : ''}{r.lai - base.lai} pts</em></div><div className="impact-meter"><span style={{width: `${r.lai}%`}}/></div><p>{r.note}</p><div className="intervention-facts"><span><b>₹{r.cost}</b> estimated cost</span><span><b>{r.co2} kg</b> CO₂e estimate</span></div></div>)}</div><div className="table-note">Ranking considers LAI only in this MVP. A future multi-objective optimizer should expose policy weights for cost, carbon, equity and feasibility.</div></section><button className="btn btn-primary" onClick={() => setPage('Scenario Simulator')}>Adjust scenario assumptions <ChevronRight size={16}/></button></div>;
}

function TrustPage({ events, tampered, tamperEvent, refresh }: { events: SensorEvent[]; tampered: boolean; tamperEvent: () => void; refresh: number }) {
  return <div className="content-stack"><div className="trust-hero"><div className="trust-shield"><ShieldCheck size={27}/></div><div><span className="hero-kicker">DEMO TRUST WORKFLOW</span><h2>{tampered ? 'Tampered payload rejected' : 'Integrity checks are demonstrable'}</h2><p>{tampered ? 'The modified event is excluded from trusted inputs. Downstream simulation state remains unchanged.' : 'Inspect sample event validation and trigger a payload-tampering demonstration.'}</p></div><span className={`trust-state ${tampered ? 'rejected' : ''}`}><i/> {tampered ? 'TAMPER DETECTED' : 'DEMO CHECKS'}</span></div><div className="metric-grid three-metrics"><MetricCard title="Accepted events" value={String(events.filter(e => e.status === 'Accepted').length)} tone="green" icon={<ShieldCheck size={18}/>} foot="Passed demo checks"/><MetricCard title="Rejected events" value={String(events.filter(e => e.status === 'Rejected').length)} tone="coral" icon={<ShieldX size={18}/>} foot="Excluded from trusted inputs"/><MetricCard title="Audit chain" value="Ready" tone="violet" icon={<GitBranch size={18}/>} foot="Demo hashes shown below"/></div><section className="panel"><SectionTitle title="Event verification log" subtitle="Synthetic sensor events with explicit acceptance and rejection reasons" action={<button className="btn btn-quiet btn-small" onClick={tamperEvent}>{tampered ? <RefreshCw size={14}/> : <AlertTriangle size={14}/>} {tampered ? 'Reset demo' : 'Simulate tampering'}</button>}/><EventTable events={events}/></section><div className="two-col-layout"><section className="panel trust-steps"><SectionTitle title="Verification pipeline" subtitle="Required checks before an event is trusted"/>{[{n:'01',title:'Schema & range',desc:'Required fields, allowed metric and configured value range.'},{n:'02',title:'Signature',desc:'Ed25519 signature checked against the registered public key in backend mode.'},{n:'03',title:'Replay protection',desc:'Sequence number and timestamp policy reject replayed or stale events.'},{n:'04',title:'Audit chain',desc:'SHA-256 chained entries allow integrity verification of audit history.'}].map(s => <div className="trust-step" key={s.n}><div>{s.n}</div><section><strong>{s.title}</strong><p>{s.desc}</p></section><Check size={16}/></div>)}</section><section className="panel limitation-panel"><div className="limitation-icon"><AlertTriangle size={19}/></div><h3>Security limitation</h3><p>A valid signature proves integrity and authenticity relative to a key; it does not prove a physical measurement is true. The browser demo uses illustrative verification states. Production trust requires protected keys, rotation, access control and threat-specific review.</p><div className="hash-preview"><span>Latest demo hash</span><code>sha256: 8f3a6d1c…c91d</code><span>Refresh count: {refresh}</span></div></section></div></div>;
}
function EventTable({ events }: { events: SensorEvent[] }) { return <div className="table-wrap"><table className="events-table"><thead><tr><th>Event</th><th>Source / metric</th><th>Value</th><th>Verification</th><th>Event hash</th></tr></thead><tbody>{events.map(e => <tr key={e.id}><td><strong>{e.id}</strong><small>{e.time}</small></td><td><strong>{e.source}</strong><small>{e.metric}</small></td><td>{e.value}</td><td><span className={`event-status ${e.status.toLowerCase()}`}>{e.status === 'Accepted' ? <Check size={12}/> : <ShieldX size={12}/>} {e.status}</span><small className="event-reason">{e.reason}</small></td><td><code>{e.hash}</code></td></tr>)}</tbody></table></div>; }

function DataSourcesPage({ events, setPage }: { events: SensorEvent[]; setPage: (s: string) => void }) {
  const sources = [ {name:'Synthetic weather adapter',kind:'Weather',status:'Available',last:'07:42:16',refresh:'Scenario-driven',quality:'Illustrative'},{name:'Synthetic transport adapter',kind:'Mobility',status:'Available',last:'07:41:20',refresh:'Scenario-driven',quality:'Illustrative'},{name:'Campus energy adapter',kind:'IoT / Energy',status:'Available',last:'07:40:02',refresh:'Scenario-driven',quality:'Illustrative'},{name:'Signed demo events',kind:'Trust',status:'Available',last:'07:42:16',refresh:'On demo action',quality:`${events.filter(e=>e.status==='Accepted').length} accepted / ${events.filter(e=>e.status==='Rejected').length} rejected`},{name:'Official weather service',kind:'External API',status:'Not connected',last:'—',refresh:'Not configured',quality:'No live data'} ];
  return <div className="content-stack"><div className="info-banner"><RadioTower size={18}/><div><strong>Source transparency</strong><p>All current data is synthetic. Live feeds and official warnings are not connected, and source status must not be interpreted as real-world conditions.</p></div></div><div className="metric-grid three-metrics"><MetricCard title="Available demo adapters" value="4" tone="green" icon={<Check size={18}/>} foot="Synthetic-first"/><MetricCard title="External feeds" value="0" tone="orange" icon={<Wifi size={18}/>} foot="No live integrations"/><MetricCard title="Rejected events" value={String(events.filter(e=>e.status==='Rejected').length)} tone="coral" icon={<ShieldX size={18}/>} foot="Not applied to trusted state"/></div><section className="panel"><SectionTitle title="Data source catalog" subtitle="Adapter state, freshness and validation"/><div className="table-wrap"><table className="events-table sources-table"><thead><tr><th>Source</th><th>Type</th><th>Status</th><th>Last update</th><th>Refresh policy</th><th>Quality</th></tr></thead><tbody>{sources.map(s => <tr key={s.name}><td><strong>{s.name}</strong></td><td>{s.kind}</td><td><span className={`source-status ${s.status === 'Available' ? 'available' : 'offline'}`}><i/> {s.status}</span></td><td>{s.last}</td><td>{s.refresh}</td><td>{s.quality}</td></tr>)}</tbody></table></div></section><section className="panel"><SectionTitle title="Quality rules" subtitle="Configured checks in the trust workflow"/><div className="quality-grid">{[{title:'Schema validation',desc:'Required fields and schema version',icon:<Check size={17}/>},{title:'Range validation',desc:'Metric-specific permitted ranges',icon:<Gauge size={17}/>},{title:'Freshness',desc:'Timestamp age and staleness',icon:<RefreshCw size={17}/>},{title:'Signature & replay',desc:'Authenticity and sequence checks',icon:<ShieldCheck size={17}/>}].map(q => <div className="quality-item" key={q.title}><div>{q.icon}</div><strong>{q.title}</strong><p>{q.desc}</p></div>)}</div><button className="btn btn-quiet" onClick={() => setPage('Trust Center')}>Open Trust Center <ChevronRight size={15}/></button></section></div>;
}

function SettingsPage({ settings, setSettings }: { settings: {demo:boolean; notifications:boolean; metric:string}; setSettings: React.Dispatch<React.SetStateAction<{demo:boolean; notifications:boolean; metric:string}>> }) {
  return <div className="content-stack settings-layout"><section className="panel"><SectionTitle title="Workspace preferences" subtitle="These settings apply to this browser demo"/><div className="setting-row"><div className="setting-icon"><Activity size={18}/></div><div className="setting-copy"><strong>Demo mode</strong><p>Use deterministic synthetic data without an API key.</p></div><button className={`toggle ${settings.demo ? 'on' : ''}`} role="switch" aria-checked={settings.demo} onClick={() => setSettings(s => ({...s, demo:!s.demo}))}><i/></button></div><div className="setting-row"><div className="setting-icon"><Bell size={18}/></div><div className="setting-copy"><strong>In-app notifications</strong><p>Show sample event and scenario notifications.</p></div><button className={`toggle ${settings.notifications ? 'on' : ''}`} role="switch" aria-checked={settings.notifications} onClick={() => setSettings(s => ({...s, notifications:!s.notifications}))}><i/></button></div><div className="setting-row"><div className="setting-icon"><BookOpen size={18}/></div><div className="setting-copy"><strong>Primary education metric</strong><p>Choose the outcome emphasized in the dashboard.</p></div><select value={settings.metric} onChange={e => setSettings(s => ({...s,metric:e.target.value}))}><option value="LAI">Learning Access Index</option><option value="ECI">Education Continuity Index</option></select></div></section><section className="panel"><SectionTitle title="Model assumptions" subtitle="Transparent prototype configuration"/><div className="assumption-list"><div><span>Rainfall weight</span><b>32%</b></div><div><span>Heat weight</span><b>18%</b></div><div><span>Power weight</span><b>28%</b></div><div><span>Transport weight</span><b>22%</b></div></div><div className="info-banner compact"><AlertTriangle size={17}/><div><strong>Not validated for operational decisions</strong><p>Weights and thresholds are illustrative defaults and must be calibrated with domain experts and validated data before deployment.</p></div></div></section><section className="panel"><SectionTitle title="About this prototype"/><div className="about-row"><div className="brand-mark"><Activity size={20}/></div><div><strong>PulseTwin v1.0.0</strong><p>AI-assisted education continuity · digital twins · trusted intervention planning</p><span>Frontend demo adapter · backend-ready architecture</span></div></div></section></div>;
}
